(function(){
  CardSpoke_MODS.register('focus-keeper', {
    meta: {
      name: 'Focus Keeper',
      type: 'Plugin',
      version: '1.0.0',
      creator: 'CardSpoke Team',
      description: 'Adds a desk-lamp focus ring when editing cards',
      releaseDate: '2024-10-20',
      source: 'official'
    },
    onCardRender(ctx, card, el){
      if(!el) return;
      const halo = document.createElement('div');
      halo.className = 'fk-focus-halo';
      el.classList.add('fk-card-shell');
      el.appendChild(halo);
    },
    onDisable(){
      document.querySelectorAll('.fk-focus-halo').forEach(n => n.remove());
      document.querySelectorAll('.fk-card-shell').forEach(n => n.classList.remove('fk-card-shell'));
    }
  });
})();
